function aggregate_elements(list_of_object, propname) {
  let result = [];
  for (let i = 0; i < list_of_object.length; i++) {
    let obj = list_of_object[i];
    let arr = obj[propname];
    for (let j = 0; j < arr.length; j++) {
      result.push(arr[j]);
    }
  }
  return result;
}
