function animateMouseTo(elem, callback) {
  let cursor = document.getElementById('fake-cursor');
  if (!cursor) {
    cursor = document.createElement('div');
    cursor.id = 'fake-cursor';
    Object.assign(cursor.style, {
      position: 'fixed',
      width: '15px',
      height: '15px',
      background: 'lime',
      borderRadius: '50%',
      pointerEvents: 'none',
      zIndex: 9999,
      left: '0px',
      top: '0px',
      transition: 'left 1s ease, top 1s ease'
    });
    document.body.appendChild(cursor);
  }
  const rect = elem.getBoundingClientRect();
  const targetX = rect.left + rect.width / 2 - 10;
  const targetY = rect.top + rect.height / 2 - 10;
  requestAnimationFrame(() => {
    cursor.style.left = `${targetX}px`;
    cursor.style.top = `${targetY}px`;
  });
  setTimeout(callback, 2000);
}
function animatePropertyX(elem, prop, start_middle_end, msDuration, forwards, easing, delay) {
  let kflist = [];
  for (const perc in start_middle_end) {
    let o = {};
    let val = start_middle_end[perc];
    o[prop] = isString(val) || prop == 'opacity' ? val : '' + val + 'px';
    kflist.push(o);
  }
  let opts = { duration: msDuration, fill: valf(forwards, 'none'), easing: valf(easing, 'ease-it-out'), delay: valf(delay, 0) };
  elem.animate(kflist, opts);
}
function annotate(sp) {
  for (const k in sp) {
    let node = sp[k];
    node.pool = [];
    let pool = makePool(node);
    for (const oid in pool) {
      let o = pool[oid];
      if (!evalCond(o, node)) continue;
      if (nundef(o.RSG)) o.RSG = {};
      let rsg = o.RSG;
      rsg[k] = true;
      node.pool.push(oid);
    }
  }
}
function appendToSVG(svgElement, htmlCode) {
  if (!(svgElement instanceof SVGElement)) {
    throw new Error("First argument must be an SVG element.");
  }
  svgElement.innerHTML += htmlCode;
}
