function arrMaxContiguous(arr) {
  let cnt = 0, el = arr[0], max = 0;
  for (let i = 0; i < arr.length; i++) {
    let a = arr[i];
    if (a == el) cnt++;
    else {
      el = a;
      if (cnt > max) max = cnt;
      cnt = 1;
    }
  }
  return max;
}
