function cairoTiling(container, rows, cols, w = 100, h = 100) {
  container.style.position = 'relative';
  container.innerHTML = '';
  for (let r = 0; r < rows; r++) {
    const y = r * h;
    const xOffset = (r % 2) * (w / 2);
    for (let c = 0; c < cols; c++) {
      const x = c * w + xOffset;
      const flip = (r + c) % 2 === 1;
      drawCairoTile(container, x, y, w, h, flip, '#ccc');
    }
  }
}
