    let resultR = Math.round(hardLight(baseR, blendR) * 255);
    let resultG = Math.round(hardLight(baseG, blendG) * 255);
    let resultB = Math.round(hardLight(baseB, blendB) * 255);
    return colorRgbArgsToHex79(resultR, resultG, resultB);
