async function ftest1() {
  await DAInit();
  let names = await loadStaticYaml("y/food/foodnames.yaml");
  let savory = await loadStaticJson("y/food/recsoups.json");
  let sweets = await loadStaticJson("y/food/recsweet.json");
  let pb = await loadStaticJson("y/food/plantbased.json");
  let fruits = await loadStaticJson("y/food/fruit.json");
  let veggies = await loadStaticJson("y/food/vegetables.json");
  M.recipes = deepMerge(savory, sweets);
  M.foodItems = deepMerge(pb, fruits, veggies);
  M.recipeDict = list2dict(M.recipes, 'name');//console.log(M.recipeDict);
  M.foodDict = list2dict(M.foodItems, 'name');
  let keys = Object.keys(M.recipeDict).concat(Object.keys(M.foodDict));
  let foodi = {};
  for (const name in names) {
    let key = keys.find(x => x.startsWith(name));
    if (key) {
      console.log("FOUND:", name, "->", key);
    }
    let k = normalizeString(names[name]);
    let rec = M.recipeDict[name] || M.foodDict[name];
    if (rec) {
      foodi[k] = rec;
    } else {
      console.log("MISSING:", name);
    }
  }
  console.log(Object.keys(foodi));
  downloadAsYaml(foodi, "foods");
}
function gCanvas(area, w, h, color, originInCenter = true) {
  let dParent = mBy(area);
  let div = stage3_prepContainer(dParent);
  div.style.width = w + 'px';
  div.style.height = h + 'px';
  let svg = gSvg();
  let style = `margin:0;padding:0;position:absolute;top:0px;left:0px;width:100%;height:100%;`
  svg.setAttribute('style', style);
  mColor(svg, color);
  div.appendChild(svg);
  let g = gG();
  if (originInCenter) g.style.transform = "translate(50%, 50%)";
  svg.appendChild(g);
  return g;
}
function gFg(g, color, thickness) { g.setAttribute('stroke', color); if (thickness) g.setAttribute('stroke-width', thickness); }
