function getMainAndAccentColor(emoji, fontSize = 128) {
  return new Promise((resolve) => {
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    canvas.width = fontSize * 2;
    canvas.height = fontSize * 2;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = `${fontSize}px "Noto Color Emoji","Apple Color Emoji","Segoe UI Emoji"`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    let txt = decodeHtmlEntity(emoji);
    ctx.fillText(txt, canvas.width / 2, canvas.height / 2);
    const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
    function colorDistance(c1, c2) {
      return Math.sqrt(
        (c1.r - c2.r) ** 2 +
        (c1.g - c2.g) ** 2 +
        (c1.b - c2.b) ** 2
      );
    }
    function isIgnoredColor(r, g, b) {
      const brightness = (r + g + b) / 3;
      if (brightness > 245) return true;
      if (brightness < 15) return true;
      const max = Math.max(r, g, b);
      const min = Math.min(r, g, b);
      if (max - min < 10) return true;
      return false;
    }
    const clusters = [];
    const threshold = 28;
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const a = data[i + 3];
      if (a < 50 || isIgnoredColor(r, g, b)) continue;
      let added = false;
      for (const cluster of clusters) {
        if (colorDistance(cluster.color, { r, g, b }) < threshold) {
          cluster.count++;
          cluster.color.r = (cluster.color.r + r) / 2;
          cluster.color.g = (cluster.color.g + g) / 2;
          cluster.color.b = (cluster.color.b + b) / 2;
          added = true;
          break;
        }
      }
      if (!added) {
        clusters.push({
          color: { r, g, b },
          count: 1,
        });
      }
    }
    clusters.sort((a, b) => b.count - a.count);
    const main = clusters[0]?.color;
    const accent = clusters.find(c =>
      colorDistance(c.color, main) > 60
    )?.color;
    resolve({
      main: main ? `rgb(${Math.round(main.r)}, ${Math.round(main.g)}, ${Math.round(main.b)})` : null,
      accent: accent ? `rgb(${Math.round(accent.r)}, ${Math.round(accent.g)}, ${Math.round(accent.b)})` : null,
    });
  });
}
function getMaxNonOverlappingSameLength(listOfArrays) {
  const keyToArraysMap = new Map();
  listOfArrays.forEach((arr, index) => {
    arr.forEach(obj => {
      if (!keyToArraysMap.has(obj.key)) keyToArraysMap.set(obj.key, []);
      keyToArraysMap.get(obj.key).push(index);
    });
  });
  const conflictScores = listOfArrays.map((arr, index) => {
    const overlappingIndices = new Set();
    arr.forEach(obj => {
      keyToArraysMap.get(obj.key).forEach(otherIndex => {
        if (otherIndex !== index) overlappingIndices.add(otherIndex);
      });
    });
    return { index, score: overlappingIndices.size };
  });
  conflictScores.sort((a, b) => a.score - b.score);
  const finalResult = [];
  const occupiedKeys = new Set();
  for (const item of conflictScores) {
    const currentSet = listOfArrays[item.index];
    const hasOverlap = currentSet.some(obj => occupiedKeys.has(obj.key));
    if (!hasOverlap) {
      finalResult.push(currentSet);
      currentSet.forEach(obj => occupiedKeys.add(obj.key));
    }
  }
  return finalResult;
}
