function getQuadSegments(x, y, sz) {
  let res = {};
  let list = getQuadCornerList(x, y, sz);
  for (let i = 0; i < list.length / 2; i++) {
    let x1 = list[2 * i];
    let y1 = list[2 * i + 1];
    let x2 = list[2 * ((i + 1) % 6)];
    let y2 = list[2 * ((i + 1) % 6) + 1];
    let id = `s${x1}_${y1}_${x2}_${y2}`;
    res[id] = { x1, y1, x2, y2 }
  }
  return res;
}
