function getUniqueRepresentativeSets(listOfArrays) {
  const seenKeys = new Set();
  const result = [];
  for (const arr of listOfArrays) {
    let hasNewKey = false;
    for (const obj of arr) {
      if (!seenKeys.has(obj.key)) {
        hasNewKey = true;
        break;
      }
    }
    if (hasNewKey) {
      result.push(arr);
      for (const obj of arr) {
        seenKeys.add(obj.key);
      }
    }
  }
  return result;
}
