function isAlphanumeric(s) { for (const ch of s) { if (!isLetter(ch) && !isDigit(ch)) return false; } return isLetter(s[0]); }
function isAncestorOf(elem, elemAnc) {
  while (elem) {
    if (elem === elemAnc) {
      return true;
    }
    elem = elem.parentNode;
  }
  return false;
}
