function isGrayColor(color, diff = 60) {
  const rgb = colorHexToRgbObject(color);
  return Math.abs(rgb.r - rgb.g) + Math.abs(rgb.r - rgb.b) + Math.abs(rgb.g - rgb.b) < 3 * diff;
}
