function parseEmojiTable(tableElement) {
  const rows = tableElement.querySelectorAll("tr");
  const results = [];
  rows.forEach(tr => {
    const tds = tr.querySelectorAll("td");
    if (tds.length < 10) return;
    const pngs = [
      tds[0].querySelector("img")?.src || null,
      tds[1].querySelector("img")?.src || null,
      tds[2].querySelector("img")?.src || null,
    ];
    const dash = tds[3].textContent.trim();
    const emoji = tds[4].textContent.trim();
    const name = tds[5].textContent.trim();
    const shortcode = tds[6].textContent.trim();
    const unicodeText = tds[7].textContent.trim();
    const pngName = tds[8].textContent.trim();
    const position = tds[9].textContent.trim();
    const codepoints = unicodeText
      .split(/\s+/)
      .map(s => s.replace("U+", "").toLowerCase());
    results.push({
      pngs,
      emoji,
      name,
      shortcode,
      codepoints,
      pngName,
      position
    });
  });
  return results;
}
function pentagonTessellationCenters(rows, cols, w, h) {
  const centers = [];
  for (let r = 0; r < rows; r++) {
    const y = r * h;
    const xOffset = (r % 2) * (w / 2);
    for (let c = 0; c < cols; c++) {
      const x = c * w + xOffset;
      centers.push({ x, y });
    }
  }
  return centers;
}
function placeCircles(dParent, n, sz, color) {
  let [w, h] = [mGetStyle(dParent, 'w'), mGetStyle(dParent, 'h')];
  let [radx, rady] = [w / 2, h / 2];
  const goldenAngle = Math.PI * (3 - Math.sqrt(5));
  const circles = [];
  for (let i = 0; i < n; i++) {
    const angle = i * goldenAngle;
    const distance = Math.sqrt(i / n);
    let x = radx + distance * radx * Math.cos(angle);
    let y = rady + distance * rady * Math.sin(angle);
    let o = placeCircle(dParent, x, y, sz, color);
    circles.push(o);
  }
  return circles;
}
function placeCirclesRandom(dParent, n, sz, color, rand = 0.2) {
  let [w, h] = [mGetStyle(dParent, 'w'), mGetStyle(dParent, 'h')];
  let [radx, rady] = [w / 2, h / 2];
  const goldenAngle = Math.PI * (3 - Math.sqrt(5));
  const circles = [];
  for (let i = 0; i < n; i++) {
    const angle = i * goldenAngle + (Math.random() - 0.5) * goldenAngle * rand;
    const distance = Math.sqrt(i / n);
    let x = radx + distance * radx * Math.cos(angle);
    let y = rady + distance * rady * Math.sin(angle);
    let o = placeCircle(dParent, x, y, sz, color);
    circles.push(o);
  }
  return circles;
}
