function playSequence(audioCtx, secs = 5) {
  let startTime = audioCtx.currentTime;
  let osc1 = audioCtx.createOscillator();
  osc1.type = 'sine';
  osc1.frequency.setValueAtTime(442, startTime);
  osc1.connect(audioCtx.destination);
  osc1.start(startTime);
  osc1.stop(startTime + secs);
  let osc2 = audioCtx.createOscillator();
  osc2.type = 'sine';
  osc2.frequency.setValueAtTime(294, startTime + secs);
  osc2.connect(audioCtx.destination);
  osc2.start(startTime + secs);
  osc2.stop(startTime + 2 * secs);
}
function playYouTubeVideo(url, containerId) {
  const videoIdMatch = url.match(/(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]+)/);
  if (!videoIdMatch) {
    console.error("Invalid YouTube URL");
    return;
  }
  const videoId = videoIdMatch[1];
  const iframe = document.createElement("iframe");
  iframe.src = `https://www.youtube.com/embed/${videoId}?autoplay=1`;
  iframe.width = "560";
  iframe.height = "315";
  iframe.frameBorder = "0";
  iframe.allow = "autoplay; encrypted-media";
  iframe.allowFullscreen = true;
  const container = document.getElementById(containerId);
  if (!container) {
    console.error("Container not found");
    return;
  }
  container.innerHTML = ""; // Clear previous video
  container.appendChild(iframe);
}
