function resizeImage(file, maxWidth, maxHeight) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        let { width, height } = img;
        if (width > maxWidth || height > maxHeight) {
          const scale = Math.min(maxWidth / width, maxHeight / height);
          width = Math.round(width * scale);
          height = Math.round(height * scale);
        }
        canvas.width = width;
        canvas.height = height;
        ctx.drawImage(img, 0, 0, width, height);
        const resizedDataUrl = canvas.toDataURL("image/jpeg", 0.8); // Quality: 0.8 (optional)
        resolve({ dataUrl: resizedDataUrl, width, height });
      };
      img.onerror = () => {
        console.error("Error loading image.");
        reject("Error loading image.");
      };
      img.src = event.target.result;
    };
    reader.onerror = () => {
      console.error("Error reading file.");
      callback(null);
    };
    reader.readAsDataURL(file);
  });
}
function roundIfTransparentCorner(img) {
  let c = getPixTL(img);
  if (c.a != 0) {
    let parent = img.parentNode;
    if (arrChildren(parent).length <= 1) {
      let r = getRect(img.parentNode);
      mStyle(img, { round: true, h: r.h - 8, w: r.w - 8 });
    } else mStyle(img, { round: true });
  }
}
function roundToNearestMultiples(n, x = 10) {
  const lower = Math.floor(n / x) * x;
  const higher = Math.ceil(n / x) * x;
  return { lower, higher };
}
function saveFileAtClient(name, type, data) {
  if (data != null && navigator.msSaveBlob) return navigator.msSaveBlob(new Blob([data], { type: type }), name);
  let a = document.createElement('a');
  a.style.display = 'none';
  let url = window.URL.createObjectURL(new Blob([data], { type: type }));
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  simulateClick(a);
  setTimeout(function () {
    window.URL.revokeObjectURL(url);
    a.remove();
  }, 500);
}
function savePanZoomCanvas(canvas) {
  if (canvas) {
    const dataURL = canvas.toDataURL('image/png');
    const link = document.createElement('a');
    link.href = dataURL;
    link.download = 'canvas-image.png';
    link.click();
  }
}
function scaleDiv(div, sc) {
  const currentWidth = div.offsetWidth;
  const currentHeight = div.offsetHeight;
  const newWidth = currentWidth * sc;
  const newHeight = currentHeight * sc;
  div.style.width = `${newWidth}px`;
  div.style.height = `${newHeight}px`;
}
function scaleDivAndContent(wrapper, sc) {
  const content = wrapper.firstElementChild;
  if (!wrapper.dataset.originalWidth) {
    wrapper.dataset.originalWidth = content.offsetWidth;
    wrapper.dataset.originalHeight = content.offsetHeight;
  }
  const originalWidth = wrapper.dataset.originalWidth;
  const originalHeight = wrapper.dataset.originalHeight;
  const newWidth = 300 + originalWidth * sc;
  const newHeight = originalHeight * sc;
  wrapper.style.width = `${newWidth}px`;
  wrapper.style.height = `${newHeight}px`;
  content.style.transform = `scale(${sc})`;
}
function scaleElement(wrapper, sc) {
  const content = wrapper.firstElementChild;
  if (!content) return;
  if (!wrapper.dataset.originalWidth) {
    wrapper.dataset.originalWidth = content.offsetWidth;
    wrapper.dataset.originalHeight = content.offsetHeight;
  }
  const originalWidth = wrapper.dataset.originalWidth;
  const originalHeight = wrapper.dataset.originalHeight;
  const newWidth = originalWidth * sc;
  const newHeight = originalHeight * sc;
  wrapper.style.width = `${newWidth}px`;
  wrapper.style.height = `${newHeight}px`;
  content.style.transform = `scale(${sc})`;
  content.style.transformOrigin = 'top left';
}
