function sortDicolor(di) {
  if (nundef(di)) di = jsCopy(M.dicolor);
  let dinew = {};
  let kbucket = Object.keys(di);
  kbucket.sort();
  for (const k of kbucket) {
    let o = di[k];
    let di_bucket_new = {};
    let kc = Object.keys(o);
    kc.sort();
    for (const k1 of kc) {
      di_bucket_new[k1] = o[k1];
    }
    dinew[k] = di_bucket_new;
  }
  downloadAsYaml(dinew, 'dicolor')
}
